    #endregion
    public void NotesPatterns_ProperlyQualifiesNotesText(string note, CallBillability billability)
    {
        // Assemble and Act
        var result = NotesPatterns.MatchPatterns(note);
        var matches = result.MatchedPatterns;

        // Assert
        bool equality = billability != CallBillability.Unknown ? matches != string.Empty : matches == string.Empty;
        Assert.Equal(result.Billability, billability);
        Assert.True(equality);
    }

    #region Summary Theory
    [
        Theory,
