    #endregion
    public void NotesPatterns_ProperlyQualifiesSummaryText(string summary, CallBillability billability)
    {
        // Assemble and Act
        var result = NotesPatterns.MatchPatterns(summary);
        var matches = result.MatchedPatterns;

        // Assert
        bool equality = billability != CallBillability.Unknown ? matches != string.Empty : matches == string.Empty;
        Assert.Equal(result.Billability, billability);
        Assert.True(equality);
    }
